namespace { HINSTANCE s_module=nullptr;void Copy(char*b,unsigned n,const char*s){if(b&&n)strncpy_s(b,n,s?s:"",_TRUNCATE);} char* LastSep(char* p){char*a=strrchr(p,'\\'),*b=strrchr(p,'/');return !a?b:!b?a:(a>b?a:b);} const char* LastSep(const char*p){const char*a=strrchr(p,'\\'),*b=strrchr(p,'/');return !a?b:!b?a:(a>b?a:b);} }
int OsPathGetRootChars(const char*p){if(!p)return 0;if(p[0]&&p[1]==':')return p[2]=='\\'||p[2]=='/'?3:2;if((p[0]=='\\'||p[0]=='/')&&(p[1]=='\\'||p[1]=='/')){const char*q=p+2;for(int slash=0;*q;++q)if(*q=='\\'||*q=='/')if(++slash==2)return int(q-p+1);}return (*p=='\\'||*p=='/')?1:0;}LPSTR __stdcall OsGetCommandLine(){return GetCommandLineA();}
void __fastcall OsGetExePath(char*b,DWORD n){GetModuleFileNameA(s_module,b,n);OsPathStripFilename(b);}void __fastcall OsGetExeName(char*b,DWORD n){char path[MAX_PATH]{};GetModuleFileNameA(s_module,path,MAX_PATH);OsPathGetFilename(path,b,n);}void __fastcall OsGetStormName(char*b,DWORD n){Copy(b,n,"Storm.dll");}int __fastcall OsGetModuleName(HMODULE m,char*b,DWORD n){return int(GetModuleFileNameA(m?m:s_module,b,n));}int __fastcall OsSetModuleHandle(HINSTANCE m,HINSTANCE){s_module=m;return 1;}void OsClearModuleHandle(){s_module=nullptr;}
void OsPathStripFilename(char*b){if(!b)return;char*p=LastSep(b);if(p)*p=0;else *b=0;}void OsPathStripLastDir(char*b){if(!b)return;size_t n=strlen(b);while(n&&(b[n-1]=='\\'||b[n-1]=='/'))b[--n]=0;OsPathStripFilename(b);}void OsPathGetFilename(const char*p,char*b,unsigned n){const char*a=p?LastSep(p):nullptr;Copy(b,n,a?a+1:p);}void OsPathGetLastDirectory(const char*p,char*b,unsigned n){std::string s=p?p:"";while(!s.empty()&&(s.back()=='\\'||s.back()=='/'))s.pop_back();auto pos=s.find_last_of("\\/");Copy(b,n,pos==std::string::npos?s.c_str():s.c_str()+pos+1);}BOOL OsPathIsRelative(const char*p){return p&&OsPathGetRootChars(p)==0;}int OsPathHasInvalidChars(const char*p){return p&&strpbrk(p,"<>\"|")!=nullptr;}int OsFileNameHasInvalidChars(const char*p){return p&&strpbrk(p,"<>:\"/\\|?*")!=nullptr;}int OsFileNameIsValid(const char*p){return p&&*p&&!OsFileNameHasInvalidChars(p);}void __fastcall OsGetSystemFontDirectory(char*b,UINT n){GetWindowsDirectoryA(b,n);strcat_s(b,n,"\\Fonts");}void OsBuildFontFilePath(char*b,const char*f,unsigned n){OsGetSystemFontDirectory(b,n);strcat_s(b,n,"\\");strcat_s(b,n,f?f:"");}
